#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // No strings provided (only program name)
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    // Too many arguments (limit is 0x41 == 65, including program name)
    if (argc > 0x41) {
        puts("TOO_MANY");
        return 0;
    }
    // Length limit for each argument: 0x400 == 1024 characters
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > 0x400) {
            puts("TOO_LONG");
            return 0;
        }
    }
    // Compute longest common prefix among all arguments
    const char *first = argv[1];
    size_t prefix_len = strlen(first);
    for (int i = 2; i < argc && prefix_len > 0; ++i) {
        const char *s = argv[i];
        size_t j = 0;
        while (j < prefix_len && first[j] == s[j]) {
            ++j;
        }
        prefix_len = j;
    }
    // Output the prefix (may be empty) followed by a newline
    if (prefix_len > 0) {
        fwrite(first, 1, prefix_len, stdout);
    }
    putchar('\n');
    return 0;
}
